public final class KasabaSocial extends JavaPlugin implements Listener,NetworkFeatures,TabCompleter {
 AtomicData data;HubApi hub;AkceApi bank;RoleAccess roles;Screens screens;Fishing fishing;
 private NamespacedKey menuKey;private final Map<UUID,Long> used=new HashMap<>(),actions=new HashMap<>(),messageAt=new HashMap<>();
 private final Map<UUID,Set<UUID>> hidden=new HashMap<>();private final Map<UUID,Long> activity=new HashMap<>();private final Set<UUID> flyers=new HashSet<>();private long lastTick;
 @Override public void onEnable(){try{data=new AtomicData(getDataFolder().toPath().resolve("veriler.yml"));hub=Objects.requireNonNull(Bukkit.getServicesManager().load(HubApi.class));bank=Objects.requireNonNull(Bukkit.getServicesManager().load(AkceApi.class));roles=Objects.requireNonNull(Bukkit.getServicesManager().load(RoleAccess.class));}catch(Exception e){getLogger().log(java.util.logging.Level.SEVERE,"Sosyal sistem başlatılamadı; veriler korundu.",e);Bukkit.getPluginManager().disablePlugin(this);return;}
  screens=new Screens(this);menuKey=new NamespacedKey(this,"lobi-araci");fishing=new Fishing(this);Bukkit.getPluginManager().registerEvents(this,this);Bukkit.getPluginManager().registerEvents(fishing,this);
  for(String command:List.of("vip","market","arkadas","mesaj","fisla","gorunurluk","fly","olta","sat"))getCommand(command).setTabCompleter(this);
  Bukkit.getServicesManager().register(NetworkFeatures.class,this,this,ServicePriority.Normal);lastTick=System.currentTimeMillis();Bukkit.getScheduler().runTaskTimer(this,this::tick,20,20);Bukkit.getScheduler().runTaskTimer(this,this::settle,20,100);Bukkit.getScheduler().runTaskTimer(this,this::saveActivity,1200,1200);
 }
 @Override public void onDisable(){if(data!=null)saveActivity();for(Player viewer:Bukkit.getOnlinePlayers()){for(UUID id:hidden.getOrDefault(viewer.getUniqueId(),Set.of())){Player target=Bukkit.getPlayer(id);if(target!=null)viewer.showPlayer(this,target);}removeTools(viewer);}for(UUID id:flyers){Player p=Bukkit.getPlayer(id);if(p!=null&&p.getGameMode()!=GameMode.CREATIVE&&p.getGameMode()!=GameMode.SPECTATOR){p.setFlying(false);p.setAllowFlight(false);}}Bukkit.getServicesManager().unregisterAll(this);}
 boolean authenticated(Player p){AuthState state=Bukkit.getServicesManager().load(AuthState.class);return p.isOnline()&&state!=null&&state.authenticated(p.getUniqueId());}
 void ready(Player p,boolean social){if(!authenticated(p))throw new IllegalArgumentException("Önce kayıt/giriş işlemini tamamla.");if(social&&!hub.socialArea(p.getUniqueId()))throw new IllegalArgumentException("Bu işlemi yalnız spawn ve lobilerde kullanabilirsin.");}
 void tell(CommandSender p,String text){p.sendMessage("§6[Kasaba] §r"+text);}
 @Override public boolean vip(Player p){return roles.vip(p);}
 @Override public boolean pay(Player p,BigDecimal amount,String transaction){ready(p,false);return bank.withdraw(p.getUniqueId(),amount,transaction);}
 @Override public boolean pay(UUID p,BigDecimal amount,String transaction){return bank.withdraw(p,amount,transaction);}
 @Override public void beforeGame(Player p){removeTools(p);}
 private String norm(String s){return s.toLowerCase(Locale.ROOT).replace('ı','i').replace('ş','s').replace('ç','c').replace('ğ','g').replace('ü','u').replace('ö','o');}
 String playerName(UUID id){Player player=Bukkit.getPlayer(id);return player==null?data.get().getString("players."+id+".name","Bilinmeyen oyuncu"):player.getName();}
 UUID known(String name){Player p=Bukkit.getPlayerExact(name);if(p!=null&&authenticated(p))return p.getUniqueId();var section=data.get().getConfigurationSection("players");if(section!=null)for(String key:section.getKeys(false))if(name.equalsIgnoreCase(data.get().getString("players."+key+".name")))return UUID.fromString(key);throw new IllegalArgumentException("Oyuncu sunucuya daha önce giriş yapmış olmalı.");}
 Player online(String name){Player p=Bukkit.getPlayerExact(name);if(p==null&&name.matches("[0-9]+"))p=Bukkit.getOnlinePlayers().stream().filter(v->v.getEntityId()==Integer.parseInt(name)).findFirst().orElse(null);if(p==null||!authenticated(p))throw new IllegalArgumentException("Oyuncu çevrimdışı.");return p;}
 boolean friends(UUID a,UUID b){return data.get().getBoolean("friends."+a+"."+b);}
 void request(Player p,UUID target){ready(p,true);if(target.equals(p.getUniqueId())||friends(p.getUniqueId(),target))throw new IllegalArgumentException("Bu oyuncu zaten arkadaşın veya kendinsin.");String path="requests."+target+"."+p.getUniqueId();data.update(y->y.set(path,System.currentTimeMillis()+7*NetworkRules.DAY));tell(p,"Arkadaşlık isteği gönderildi: "+playerName(target));Player to=Bukkit.getPlayer(target);if(to!=null)tell(to,p.getName()+" arkadaşlık isteği gönderdi. /arkadaş kabul "+p.getName());}
 void accept(Player p,UUID target){ready(p,true);String path="requests."+p.getUniqueId()+"."+target;if(data.get().getLong(path)<=System.currentTimeMillis())throw new IllegalArgumentException("Geçerli arkadaşlık isteği yok.");data.update(y->{y.set(path,null);y.set("requests."+target+"."+p.getUniqueId(),null);y.set("friends."+p.getUniqueId()+"."+target,true);y.set("friends."+target+"."+p.getUniqueId(),true);});tell(p,playerName(target)+" artık arkadaşın.");}
 @Override public void socialMenu(Player p){ready(p,true);List<Screens.Button> buttons=new ArrayList<>();List<String> lines=new ArrayList<>(List.of("Arkadaşlarının çevrimiçi/çevrimdışı durumunu gör; mesajlaş veya grup kur."));var friends=data.get().getConfigurationSection("friends."+p.getUniqueId());if(friends!=null)for(String key:friends.getKeys(false)){UUID id=UUID.fromString(key);Player friend=Bukkit.getPlayer(id);boolean on=friend!=null&&authenticated(friend);lines.add(playerName(id)+" • "+(on?"Çevrimiçi • Kimlik: "+friend.getEntityId():"Çevrimdışı"));buttons.add(button(playerName(id)+(on?" • Aktif":" • Çevrimdışı"),()->friendPage(p,id)));}
  buttons.add(button("Arkadaş ekle",()->screens.show(p,"Arkadaş ekle",List.of("Oyuncunun Minecraft adını yaz."),List.of(Screens.input("name","Oyuncu adı",16)),List.of(new Screens.Button("İstek gönder",r->{request(p,known(Objects.requireNonNullElse(r.getText("name"),"")));socialMenu(p);}),button("Geri",()->socialMenu(p))),true)));
  var requests=data.get().getConfigurationSection("requests."+p.getUniqueId());if(requests!=null)for(String key:requests.getKeys(false))if(requests.getLong(key)>System.currentTimeMillis()){UUID id=UUID.fromString(key);buttons.add(button("Kabul: "+playerName(id),()->{accept(p,id);socialMenu(p);}));}
  buttons.add(button("Grubum",()->Bukkit.dispatchCommand(p,"grup")));buttons.add(button("Grup kur",()->Bukkit.dispatchCommand(p,"grup oluştur")));buttons.add(button("Kapat",()->{}));screens.show(p,"Kasaba • Arkadaşlar",lines,List.of(),buttons,true);
 }
 private void friendPage(Player p,UUID id){List<Screens.Button> buttons=new ArrayList<>();buttons.add(button("Mesaj gönder",()->screens.show(p,"Mesaj • "+playerName(id),List.of("İkiniz de spawn veya lobide olmalısınız."),List.of(Screens.input("text","Mesajın",256)),List.of(new Screens.Button("Gönder",r->message(p,online(playerName(id)),Objects.requireNonNullElse(r.getText("text"),""),false)),button("Geri",()->socialMenu(p))),true)));buttons.add(button("Gruba davet et",()->Bukkit.dispatchCommand(p,"grup davet "+playerName(id))));buttons.add(button("Arkadaşlıktan çıkar",()->{data.update(y->{y.set("friends."+p.getUniqueId()+"."+id,null);y.set("friends."+id+"."+p.getUniqueId(),null);});socialMenu(p);}));buttons.add(button("Geri",()->socialMenu(p)));screens.show(p,playerName(id),List.of("Mesajlar kaydedilmez; çevrimiçi arkadaşına gönderilir."),List.of(),buttons,true);}
 private void message(Player from,Player to,String text,boolean whisper){ready(from,!whisper);ready(to,!whisper);if(from==to)throw new IllegalArgumentException("Kendine mesaj gönderemezsin.");if(whisper&&!vip(from))throw new IllegalArgumentException("/fısla VIP ayrıcalığıdır.");if(!whisper&&!friends(from.getUniqueId(),to.getUniqueId()))throw new IllegalArgumentException("Önce arkadaş olmalısınız.");if(text.isBlank()||text.length()>256)throw new IllegalArgumentException("Mesaj 1–256 karakter olmalı.");long now=System.currentTimeMillis();if(now-messageAt.getOrDefault(from.getUniqueId(),0L)<1000)throw new IllegalArgumentException("Mesajlar arasında 1 saniye bekle.");messageAt.put(from.getUniqueId(),now);String line="§d["+(whisper?"Fısıltı":"Arkadaş")+"] §f"+from.getName()+" → "+to.getName()+" » "+text.replace('§',' ');from.sendMessage(line);to.sendMessage(line);}
 @Override public void vipInfo(Player p){ready(p,false);long until=roles.vipUntil(p.getUniqueId());String state=vip(p)?until>System.currentTimeMillis()?"Kalan VIP: "+((until-System.currentTimeMillis()+3_599_999)/3_600_000)+" saat":"VIP rolün aktif.":"VIP değilsin.";screens.show(p,"Kasaba • VIP Ayrıcalıkları",List.of(state,"Adanı Yap: en fazla 2 ücretsiz arsa; 15 gün giriş yapılmazsa adalar sıfırlanır.","X Arena, 1v1, 2v2: netherit Korunma III set. X Arena becerileri 2 sn daha hızlı yenilenir.","Vampir Köylü: istediğin rol için öncelik seç. Aynı rolü isteyen VIP'ler arasında kura; rol sayısı korunur.","/fısla <oyuncu veya kimlik> <mesaj> ile özel mesaj.","BR: +3 sarı kalp, tam envanter ve inişte elitra; yere inince elitra kaldırılır.","İsim ve rol etiketi renkli. Süreler gerçek zamanla işler.","3 gün: 40 • 7 gün: 75 • 15 gün: 145 • 30 gün: 250 Akçe"),List.of(),List.of(button("VIP satın al",()->market(p)),button("Kapat",()->{})),false);}
 @Override public void market(Player p){ready(p,true);List<Screens.Button> buttons=new ArrayList<>();for(int days:List.of(3,7,15,30))buttons.add(button(days+" gün • "+NetworkRules.PRICES.get(days).toPlainString()+" Akçe",()->screens.show(p,"VIP satın al?",List.of(days+" günlük VIP: "+NetworkRules.PRICES.get(days).toPlainString()+" Akçe.","Varsa mevcut sürenin sonuna eklenir. Süre çevrimdışıyken de işler."),List.of(),List.of(button("Satın al",()->purchase(p,days)),button("Vazgeç",()->market(p))),true)));buttons.add(button("VIP ayrıcalıkları",()->vipInfo(p)));buttons.add(button("Kapat",()->{}));screens.show(p,"Kasaba • Market",List.of("Bakiyen: "+bank.balance(p.getUniqueId()).toPlainString()+" Akçe","Süre seç; satın almadan önce onay sayfası açılır."),List.of(),buttons,true);}
 private void purchase(Player p,int days){ready(p,true);String id=UUID.randomUUID().toString();long until=NetworkRules.expiry(System.currentTimeMillis(),roles.vipUntil(p.getUniqueId()),days);data.update(y->{String k="purchases."+id;y.set(k+".player",p.getUniqueId().toString());y.set(k+".days",days);y.set(k+".price",NetworkRules.PRICES.get(days).toPlainString());y.set(k+".until",until);y.set(k+".pending",true);});settle();tell(p,data.get().getBoolean("purchases."+id+".success")?"VIP satın alındı. /vip ile kalan süreni görebilirsin.":"Satın alma tamamlanmadı; bakiyeni kontrol et. Bekleyen işlem varsa otomatik tamamlanır.");}
 void creditJob(org.bukkit.configuration.file.YamlConfiguration y,String id,UUID owner,BigDecimal amount){String k="credits."+id;y.set(k+".player",owner.toString());y.set(k+".amount",amount.toPlainString());y.set(k+".pending",true);}
 void settle(){try{var credits=data.get().getConfigurationSection("credits");if(credits!=null)for(String id:credits.getKeys(false))if(data.get().getBoolean("credits."+id+".pending")){String k="credits."+id;bank.credit(UUID.fromString(data.get().getString(k+".player")),new BigDecimal(data.get().getString(k+".amount")),"sosyal:"+id);data.update(y->y.set(k+".pending",false));}
  var purchases=data.get().getConfigurationSection("purchases");if(purchases!=null)for(String id:purchases.getKeys(false)){String k="purchases."+id;if(!data.get().getBoolean(k+".pending"))continue;UUID owner=UUID.fromString(data.get().getString(k+".player"));int days=data.get().getInt(k+".days");boolean paid=bank.withdraw(owner,new BigDecimal(data.get().getString(k+".price",NetworkRules.PRICES.get(days).toPlainString())),"vip:"+id);if(paid)roles.grantVip(owner,data.get().getLong(k+".until"));data.update(y->{y.set(k+".pending",false);y.set(k+".success",paid);});}
 }catch(RuntimeException e){getLogger().log(java.util.logging.Level.WARNING,"Bekleyen ödeme korunuyor; yeniden denenecek.",e);}}
 private boolean tool(ItemStack item){return item!=null&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(menuKey);}
 private void removeTools(Player p){for(int slot=0;slot<p.getInventory().getSize();slot++)if(tool(p.getInventory().getItem(slot)))p.getInventory().setItem(slot,null);if(tool(p.getItemOnCursor()))p.setItemOnCursor(null);}
 private void tools(Player p){if(!hub.socialArea(p.getUniqueId())){removeTools(p);return;}boolean[] found=new boolean[2];for(int slot=0;slot<p.getInventory().getSize();slot++){ItemStack item=p.getInventory().getItem(slot);if(!tool(item))continue;int kind=item.getItemMeta().getPersistentDataContainer().getOrDefault(menuKey,PersistentDataType.INTEGER,0);if(kind<0||kind>1||found[kind])p.getInventory().setItem(slot,null);else found[kind]=true;}for(int kind=0;kind<2;kind++)if(!found[kind]){int preferred=6-kind,slot=p.getInventory().getItem(preferred)==null?preferred:p.getInventory().firstEmpty();if(slot<0||slot>=36)continue;boolean hide=data.get().getBoolean("players."+p.getUniqueId()+".hide");ItemStack item=new ItemStack(kind==0?(hide?Material.GRAY_DYE:Material.LIME_DYE):Material.PLAYER_HEAD);int key=kind;item.editMeta(m->{m.setDisplayName(kindName(key,hide));m.getPersistentDataContainer().set(menuKey,PersistentDataType.INTEGER,key);});p.getInventory().setItem(slot,item);}}
 private String kindName(int kind,boolean hide){return kind==1?"§bArkadaşlar ve Grup §7• Sağ tık":"§aOyuncular: "+(hide?"§7Gizli":"§aGörünür")+" §7• Sağ tıkla değiştir";}
 private void toggle(Player p){ready(p,true);String k="players."+p.getUniqueId()+".hide";boolean hide=!data.get().getBoolean(k);data.update(y->y.set(k,hide));removeTools(p);tools(p);visibility();tell(p,hide?"Lobideki oyuncular gizlendi.":"Lobideki oyuncular gösterildi.");}
 private void visibility(){for(Player viewer:Bukkit.getOnlinePlayers()){Set<UUID> old=hidden.computeIfAbsent(viewer.getUniqueId(),k->new HashSet<>());Set<UUID> next=new HashSet<>();if(hub.socialArea(viewer.getUniqueId())&&data.get().getBoolean("players."+viewer.getUniqueId()+".hide"))for(Player target:Bukkit.getOnlinePlayers())if(target!=viewer&&hub.socialArea(target.getUniqueId()))next.add(target.getUniqueId());for(UUID id:old)if(!next.contains(id)){Player target=Bukkit.getPlayer(id);if(target!=null)viewer.showPlayer(this,target);}for(UUID id:next)if(!old.contains(id)){Player target=Bukkit.getPlayer(id);if(target!=null)viewer.hidePlayer(this,target);}hidden.put(viewer.getUniqueId(),next);}}
 private void tick(){long now=System.currentTimeMillis(),elapsed=Math.min(2000,Math.max(0,now-lastTick));lastTick=now;for(Player p:Bukkit.getOnlinePlayers()){if(!authenticated(p))continue;tools(p);fishing.clean(p);if(NetworkRules.earns(hub.gameplay(p.getUniqueId()),hub.socialArea(p.getUniqueId()),p.getGameMode()==GameMode.SPECTATOR,actions.getOrDefault(p.getUniqueId(),0L),now)){long total=activity.getOrDefault(p.getUniqueId(),data.get().getLong("players."+p.getUniqueId()+".activity"))+elapsed;if(total>=900_000){String tx="activity-"+UUID.randomUUID();long carry=total-900_000;data.update(y->{y.set("players."+p.getUniqueId()+".activity",carry);creditJob(y,tx,p.getUniqueId(),new BigDecimal("0.20"));});activity.put(p.getUniqueId(),carry);tell(p,"15 dakikalık aktif oyun için +0,20 Akçe kazandın.");}else activity.put(p.getUniqueId(),total);}if(flyers.contains(p.getUniqueId())){if(roles.guide(p)){if(p.getGameMode()!=GameMode.SPECTATOR)p.setAllowFlight(true);}else{flyers.remove(p.getUniqueId());if(p.getGameMode()!=GameMode.CREATIVE&&p.getGameMode()!=GameMode.SPECTATOR){p.setFlying(false);p.setAllowFlight(false);}}}}visibility();}
 private void saveActivity(){if(data==null||activity.isEmpty())return;data.update(y->activity.forEach((id,value)->y.set("players."+id+".activity",value)));}
 private void active(Player p){if(authenticated(p)&&hub.gameplay(p.getUniqueId()))actions.put(p.getUniqueId(),System.currentTimeMillis());}
 @EventHandler(priority=EventPriority.MONITOR) public void verified(PlayerAuthenticatedEvent e){Player p=e.getPlayer();data.update(y->y.set("players."+p.getUniqueId()+".name",p.getName()));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void moved(PlayerMoveEvent e){if(!(e instanceof PlayerTeleportEvent)&&e.hasChangedBlock())active(e.getPlayer());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void broken(BlockBreakEvent e){active(e.getPlayer());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void placed(BlockPlaceEvent e){active(e.getPlayer());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void fought(EntityDamageByEntityEvent e){if(e.getFinalDamage()<=0)return;if(e.getEntity() instanceof Player p)active(p);if(e.getDamager() instanceof Player p)active(p);else if(e.getDamager() instanceof Projectile shot&&shot.getShooter() instanceof Player p)active(p);}
 @EventHandler(priority=EventPriority.MONITOR) public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();if(activity.containsKey(id)){long carried=activity.get(id);data.update(y->y.set("players."+id+".activity",carried));activity.remove(id);}actions.remove(id);used.remove(id);messageAt.remove(id);hidden.remove(id);flyers.remove(id);}
 @EventHandler(priority=EventPriority.HIGHEST) public void interact(PlayerInteractEvent e){if(!tool(e.getItem()))return;e.setCancelled(true);if(e.getHand()!=EquipmentSlot.HAND||!e.getAction().name().startsWith("RIGHT_CLICK"))return;Player p=e.getPlayer();long now=System.currentTimeMillis();if(now-used.getOrDefault(p.getUniqueId(),0L)<250)return;used.put(p.getUniqueId(),now);try{ready(p,true);if(e.getItem().getItemMeta().getPersistentDataContainer().getOrDefault(menuKey,PersistentDataType.INTEGER,0)==0)toggle(p);else socialMenu(p);}catch(RuntimeException ex){tell(p,ex.getMessage());}}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(tool(e.getCurrentItem())||tool(e.getCursor())||e.getHotbarButton()>=0&&tool(e.getWhoClicked().getInventory().getItem(e.getHotbarButton())))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(tool(e.getOldCursor()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void swap(PlayerSwapHandItemsEvent e){if(tool(e.getMainHandItem())||tool(e.getOffHandItem()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void drop(PlayerDropItemEvent e){if(tool(e.getItemDrop().getItemStack()))e.setCancelled(true);}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){tell(sender,"Bu komutu oyunda kullan.");return true;}try{ready(p,false);switch(command.getName()){
  case "vip"->vipInfo(p);case "market"->market(p);case "gorunurluk"->toggle(p);case "olta"->fishing.rod(p);case "sat"->{if(args.length!=1||!norm(args[0]).equals("balik"))throw new IllegalArgumentException("/sat balık");fishing.sell(p);}
  case "fly"->{if(!roles.guide(p))throw new IllegalArgumentException("/fly rehber ve bu yetkiyi miras alan rollere özeldir.");boolean on=flyers.add(p.getUniqueId());if(!on)flyers.remove(p.getUniqueId());p.setAllowFlight(on||p.getGameMode()==GameMode.CREATIVE||p.getGameMode()==GameMode.SPECTATOR);if(!on&&p.getGameMode()==GameMode.SURVIVAL)p.setFlying(false);tell(p,on?"Uçuş açıldı.":"Uçuş kapatıldı.");}
  case "mesaj","fisla"->{if(args.length<2)throw new IllegalArgumentException("/"+label+" <oyuncu veya kimlik> <mesaj>");message(p,online(args[0]),String.join(" ",Arrays.copyOfRange(args,1,args.length)),command.getName().equals("fisla"));}
  case "arkadas"->{ready(p,true);if(args.length==0)socialMenu(p);else if(args.length==2){UUID target=known(args[1]);switch(norm(args[0])){case "ekle"->request(p,target);case "kabul"->accept(p,target);case "sil"->data.update(y->{y.set("friends."+p.getUniqueId()+"."+target,null);y.set("friends."+target+"."+p.getUniqueId(),null);});default->throw new IllegalArgumentException("/arkadaş ekle|kabul|sil <oyuncu>");}}else throw new IllegalArgumentException("/arkadaş • /arkadaş ekle|kabul|sil <oyuncu> • /mesaj <oyuncu> <mesaj>");}
 }}catch(RuntimeException e){tell(p,e.getMessage()==null?"İşlem tamamlanamadı.":e.getMessage());}return true;}
 @Override public List<String> onTabComplete(CommandSender sender,Command c,String label,String[] a){if(c.getName().equals("sat"))return List.of("balık");if(c.getName().equals("arkadas")&&a.length==1)return List.of("ekle","kabul","sil");return Bukkit.getOnlinePlayers().stream().filter(this::authenticated).map(Player::getName).filter(n->n.toLowerCase(Locale.ROOT).startsWith(a[a.length-1].toLowerCase(Locale.ROOT))).toList();}
}
